-- Insert a tényleges adrlocality_alias táblába
INSERT INTO public.adrlocality_alias (adrlocality_id, alias_name, source)
SELECT l.id, s.alias_name, 'geonames'
FROM _adr_alias_staging s
JOIN public.adrlocality l ON l.siruta_code = s.siruta_code
ON CONFLICT DO NOTHING;

DROP TABLE _adr_alias_staging;

COMMIT;

-- Ellenőrzés
SELECT COUNT(*) AS alias_count FROM public.adrlocality_alias;